"""Mock TTS 客户端。生成固定 mp3（约 0.3s 静音，ffmpeg 可正常 concat）。"""

import asyncio
from .base import TTSClient


# 0.3s 静音 mp3（用 ffmpeg anullsrc 生成，覆盖 ID3 + MPEG 帧，ffmpeg/concat 验证通过）
_MOCK_MP3 = bytes.fromhex(
    ""
)


class MockTTSClient(TTSClient):
    """Mock TTS 客户端。

    不调任何外部 API，返回固定静音 mp3（≈0.3s）。
    用于本地开发 + CI 测试。
    """

    @property
    def provider_name(self) -> str:
        return "mock"

    async def synthesize(
        self,
        text: str,
        voice: str = "zh-CN-XiaoxiaoNeural",
        output_format: str = "mp3",
    ) -> bytes:
        # 模拟合成延迟
        await asyncio.sleep(0.3)

        # 返回静音 mp3（mock）
        # 生产实现应该用 Edge TTS / OpenAI TTS / 豆包 TTS 生成真音频
        return _MOCK_MP3 * 4  # 约 1.2s 静音
